#include <bits/stdc++.h>using namespace std; int main() {  int t = 0;   cin >> t;   while (t--)   {     int n = 0;     cin >> n;     string str;     cin >> str;     vector<int> vec(26, 0);     int ans = 0;     for (int i = 0; i < n; i++)     {       if (vec[str[i] - 'a'] == 0)       {         ans = ans + (n - i);         vec[str[i] - 'a'] = 1;       }             }     cout << ans << endl;  }}